1	// pattern: Mixed (Functional Core sweep orchestration + iOS-only imperative scheduling bridge)
2	//
3	// Background media-backup scheduling. The user-held blob backup (`blob_backup.rs`) ships
4	// the explicit "Back up media" action plus an opportunistic pass on app open; this module
5	// adds the deliberate later step — an iOS `BGProcessingTask` so an opted-in identity's
6	// iCloud mirror stays topped up without the user opening the app (media posted days ago
7	// shouldn't sit unprotected until the next launch).
8	//
9	// On fire it runs the same incremental, CID-verified, per-blob-degrading `run_blob_backup`
10	// pass for every opted-in DID. That is safe to overlap with a foreground pass: the per-DID
11	// mirror lock in `blob_backup` serializes the manifest writes, and the pass is idempotent
12	// by construction (content-addressed, immutable files), so a sweep iOS interrupts mid-run
13	// self-heals on the next pass.
14	//
15	// Scheduling is a device concern: everything that touches `BGTaskScheduler` is iOS-only,
16	// reached through objc2's BackgroundTasks binding — the same no-new-Swift bridge pattern as
17	// blob_backup's ubiquity-container call. Off-device the scheduling surface is inert. The
18	// sweep *orchestration* (`run_sweep_with`) is platform-agnostic and unit-tested.
19	//
20	// The user tunes the sweep from Settings via three app-global flags
21	// (`BackgroundBackupSettings`): whether iOS may wake the app at all, whether to require
22	// external power, and whether to skip cellular links. They are app-global (not per-DID)
23	// because the sweep is one `BGProcessingTask` covering every opted-in identity. The
24	// settings get/set commands are frontend-facing, so they (and their harness fakes) are the
25	// one part of this module the browser harness does touch.
26	
27	use crate::blob_backup;
28	use serde::{Deserialize, Serialize};
29	
30	// ── User-tunable settings (app-global) ───────────────────────────────────────
31	
32	/// Global Keychain account holding the background-backup settings JSON. App-wide (not
33	/// per-DID): the sweep is one `BGProcessingTask` covering every opted-in identity, so its
34	/// power/network policy is a single shared setting.
35	const SETTINGS_ACCOUNT: &str = "blob-backup-settings";
36	
37	/// User-tunable policy for the background media-backup sweep. App-global. Serializes as
38	/// camelCase to match the `$lib/ipc` `BackgroundBackupSettings` type.
39	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
40	#[serde(rename_all = "camelCase")]
41	pub struct BackgroundBackupSettings {
42	    /// Whether iOS may wake the app to run a backup sweep at all. Off keeps the
43	    /// opportunistic app-open pass but stops OS-scheduled wakes.
44	    pub background_enabled: bool,
45	    /// Only run the sweep while the device is on external power (charging). Off by default
46	    /// so the sweep isn't starved on devices that rarely charge on a predictable schedule.
47	    pub require_external_power: bool,
48	    /// Skip the sweep on a cellular (metered) link — a video-heavy account's mirror can be
49	    /// large. Enforced at fire time via a reachability check (`BGProcessingTaskRequest`
50	    /// can't express "Wi-Fi only").
51	    pub wifi_only: bool,
52	}
53	
54	impl Default for BackgroundBackupSettings {
55	    fn default() -> Self {
56	        Self {
57	            background_enabled: true,
58	            require_external_power: false,
59	            wifi_only: false,
60	        }
61	    }
62	}
63	
64	/// Error from the background-backup settings commands. Serializes as
65	/// `{ "code": "SCREAMING_SNAKE_CASE" }` like the sibling wallet error enums.
66	#[derive(Debug, Serialize, thiserror::Error)]
67	#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE")]
68	pub enum BackgroundBackupError {
69	    #[error("keychain error: {message}")]
70	    KeychainError { message: String },
71	    #[error("could not encode settings: {message}")]
72	    SerializationError { message: String },
73	}
74	
75	/// Read the persisted settings, or the defaults when unset or unreadable. A corrupt/
76	/// unreadable value reads as the defaults (background on), never an error — a diagnostic
77	/// hiccup must not silently disable a backup the user relies on.
78	pub(crate) fn load_settings() -> BackgroundBackupSettings {
79	    crate::keychain::get_item(SETTINGS_ACCOUNT)
80	        .ok()
81	        .and_then(|raw| serde_json::from_slice(&raw).ok())
82	        .unwrap_or_default()
83	}
84	
85	/// Tauri command: the current background-backup settings, for the Settings screen.
86	#[tauri::command]
87	pub fn get_background_backup_settings() -> BackgroundBackupSettings {
88	    load_settings()
89	}
90	
91	/// Tauri command: persist the background-backup settings and re-apply the schedule (on iOS:
92	/// submit or cancel the `BGProcessingTask` to match `background_enabled` /
93	/// `require_external_power`; `wifi_only` needs no reschedule — it is read at fire time).
94	/// Returns the stored settings.
95	#[tauri::command]
96	pub fn set_background_backup_settings(
97	    settings: BackgroundBackupSettings,
98	) -> Result<BackgroundBackupSettings, BackgroundBackupError> {
99	    let json =
100	        serde_json::to_vec(&settings).map_err(|e| BackgroundBackupError::SerializationError {
101	            message: e.to_string(),
102	        })?;
103	    crate::keychain::store_item(SETTINGS_ACCOUNT, &json).map_err(|e| {
104	        BackgroundBackupError::KeychainError {
105	            message: e.to_string(),
106	        }
107	    })?;
108	    #[cfg(target_os = "ios")]
109	    apply_schedule();
110	    Ok(settings)
111	}
