113	/// Whether the sweep should be skipped this run for network policy: `wifi_only` is on and
114	/// we are on a cellular (metered) link. Pure so the decision is unit-tested; the live
115	/// cellular check (`on_cellular`) is the iOS-only side effect.
116	#[cfg_attr(not(target_os = "ios"), allow(dead_code))]
117	pub(crate) fn should_skip_for_network(wifi_only: bool, on_cellular: bool) -> bool {
118	    wifi_only && on_cellular
119	}
120	
121	/// The `BGTaskScheduler` identifier for the media-backup processing task. MUST match the
122	/// entry in `Info.ios.plist`'s `BGTaskSchedulerPermittedIdentifiers` array — iOS refuses to
123	/// register or submit an identifier the plist doesn't permit — and is bundle-id-prefixed by
124	/// Apple convention (bundle id `dev.malpercio.identitywallet`, `tauri.conf.json`). Kept in
125	/// sync with the plist the same way the ubiquity container id is.
126	#[cfg(target_os = "ios")]
127	const BACKUP_TASK_IDENTIFIER: &str = "dev.malpercio.identitywallet.blob-backup";
128	
129	/// The earliest the system may run a scheduled task, as a delay from submission. A floor,
130	/// not a deadline — iOS picks the actual moment from usage, power, and network availability.
131	/// ~12h keeps the mirror fresh (new media is protected within a day) without asking to wake
132	/// more often than a media backup needs to.
133	#[cfg(target_os = "ios")]
134	const EARLIEST_BEGIN_AFTER_SECS: f64 = 12.0 * 60.0 * 60.0;
135	
136	/// Summary of one background sweep — counts only, for `tracing` and the unit tests.
137	#[cfg_attr(not(target_os = "ios"), allow(dead_code))]
138	#[derive(Debug, Default, PartialEq, Eq)]
139	pub(crate) struct BackupSweepReport {
140	    /// Opted-in identities the sweep attempted a pass for.
141	    pub attempted: u32,
142	    /// Attempts that completed without error.
143	    pub succeeded: u32,
144	    /// Attempts that returned an error (logged, never aborts the sweep).
145	    pub failed: u32,
146	    /// Identities skipped because the user has not opted in.
147	    pub skipped: u32,
148	}
149	
150	/// Sweep core: back up every opted-in identity, degrading per-DID — one identity's failure
151	/// is tallied and logged, never stops the others. Generic over the opt-in predicate and the
152	/// per-DID backup step so it is unit-testable without a live PDS, Keychain, or iCloud.
153	/// Sequential by design: the passes share the network and the process-global per-DID mirror
154	/// locks, and a background sweep has no reason to race them concurrently.
155	#[cfg_attr(not(target_os = "ios"), allow(dead_code))]
156	pub(crate) async fn run_sweep_with<F, Fut>(
157	    dids: &[String],
158	    is_enabled: impl Fn(&str) -> bool,
159	    backup_one: F,
160	) -> BackupSweepReport
161	where
162	    F: Fn(String) -> Fut,
163	    Fut: std::future::Future<Output = Result<(), blob_backup::BlobBackupError>>,
164	{
165	    let mut report = BackupSweepReport::default();
166	    for did in dids {
167	        if !is_enabled(did) {
168	            report.skipped += 1;
169	            continue;
170	        }
171	        report.attempted += 1;
172	        match backup_one(did.clone()).await {
173	            Ok(()) => report.succeeded += 1,
174	            Err(e) => {
175	                tracing::warn!(did = %did, error = %e, "background media backup: pass failed");
176	                report.failed += 1;
177	            }
178	        }
179	    }
180	    report
181	}
182	
183	/// Run one background backup sweep over every managed identity, backing up those opted in.
184	/// The launch handler's payload. Resolves the managed DIDs from the `IdentityStore` and
185	/// delegates to `run_sweep_with` with the real opt-in flag + per-DID backup.
186	#[cfg(target_os = "ios")]
187	pub(crate) async fn run_backup_sweep(app: &tauri::AppHandle) -> BackupSweepReport {
188	    // Honor the Wi-Fi-only preference: BGProcessingTaskRequest can't express "Wi-Fi only", so
189	    // we check the live network type here and defer to the next scheduled fire if on cellular.
190	    let settings = load_settings();
191	    if should_skip_for_network(settings.wifi_only, on_cellular()) {
192	        tracing::info!(
193	            "background media backup: skipped this run — Wi-Fi only is on and the device is on cellular"
194	        );
195	        return BackupSweepReport::default();
196	    }
197	
198	    let dids = crate::identity_store::IdentityStore
199	        .list_identities()
200	        .unwrap_or_default();
201	    let report = run_sweep_with(
202	        &dids,
203	        |did| blob_backup::is_backup_enabled(did),
204	        |did| {
205	            let app = app.clone();
206	            async move {
207	                blob_backup::run_backup_for_did(&app, &did)
208	                    .await
209	                    .map(|_| ())
210	            }
211	        },
212	    )
213	    .await;
214	    tracing::info!(
215	        attempted = report.attempted,
216	        succeeded = report.succeeded,
217	        failed = report.failed,
218	        skipped = report.skipped,
219	        "background media backup sweep complete"
220	    );
221	    report
222	}
