224	// ── iOS BGProcessingTask bridge ──────────────────────────────────────────────
225	
226	/// A `Retained<BGTask>` we promise to use soundly across threads.
227	///
228	/// iOS calls the launch handler on the main thread, but the backup sweep runs on the tokio
229	/// runtime; the worker (or the expiration handler) must call `setTaskCompletedWithSuccess`
230	/// when it finishes. objc2 conservatively leaves framework objects `!Send`, so we assert it.
231	///
232	/// SAFETY: the only `BGTask` methods we call on it are the completion methods, which Apple
233	/// documents as callable from any thread (their sample code completes the task from an
234	/// `NSOperation` completion block on a background queue), and every such call is gated behind
235	/// a one-shot atomic latch so it happens exactly once.
236	#[cfg(target_os = "ios")]
237	struct SendTask(objc2::rc::Retained<objc2_background_tasks::BGTask>);
238	
239	#[cfg(target_os = "ios")]
240	// SAFETY: see the `SendTask` doc comment — completion methods are thread-safe by Apple's
241	// contract and serialized to a single call by the `done` latch in `complete_once`.
242	unsafe impl Send for SendTask {}
243	#[cfg(target_os = "ios")]
244	// SAFETY: as above; the shared handle is only ever used to make the thread-safe completion
245	// call, so concurrent `&SendTask` access from the worker and the expiration handler is sound.
246	unsafe impl Sync for SendTask {}
247	
248	/// Mark the task complete at most once — whichever of the worker (success) or the expiration
249	/// handler (failure) reaches it first wins; the loser is a no-op. iOS treats a second
250	/// `setTaskCompletedWithSuccess` on the same task as a fatal misuse, so the latch is required.
251	#[cfg(target_os = "ios")]
252	fn complete_once(task: &SendTask, done: &std::sync::atomic::AtomicBool, success: bool) {
253	    use std::sync::atomic::Ordering;
254	    if !done.swap(true, Ordering::SeqCst) {
255	        unsafe { task.0.setTaskCompletedWithSuccess(success) };
256	    }
257	}
258	
259	/// Register the background media-backup task and submit the first request. Called once from
260	/// the Tauri `setup` hook on iOS — registration must happen before app launch completes, and
261	/// `setup` runs within `application:didFinishLaunchingWithOptions:`. Every failure is logged
262	/// rather than fatal: the opportunistic app-open pass still protects opted-in identities.
263	#[cfg(target_os = "ios")]
264	pub(crate) fn register_and_schedule(app: &tauri::AppHandle) {
265	    use block2::RcBlock;
266	    use objc2_background_tasks::{BGTask, BGTaskScheduler};
267	    use objc2_foundation::NSString;
268	    use std::ptr::NonNull;
269	
270	    let scheduler = unsafe { BGTaskScheduler::sharedScheduler() };
271	    let identifier = NSString::from_str(BACKUP_TASK_IDENTIFIER);
272	
273	    let app_for_handler = app.clone();
274	    // Escaping launch handler; iOS stores a copy for the process lifetime and calls it on the
275	    // main thread when it decides to run the task, handing us the live `BGTask`.
276	    let launch_handler = RcBlock::new(move |task_ptr: NonNull<BGTask>| {
277	        // We were handed the task with no ownership; retain it (+1) so it survives the async
278	        // sweep. Non-null by the framework's contract.
279	        let Some(task) = (unsafe { objc2::rc::Retained::retain(task_ptr.as_ptr()) }) else {
280	            return;
281	        };
282	        handle_launch(&app_for_handler, task);
283	    });
284	
285	    let registered = unsafe {
286	        scheduler.registerForTaskWithIdentifier_usingQueue_launchHandler(
287	            &identifier,
288	            None, // run the launch handler on the default background queue
289	            &launch_handler,
290	        )
291	    };
292	    if !registered {
293	        tracing::warn!(
294	            "background media backup: BGTaskScheduler refused to register the task identifier"
295	        );
296	        return;
297	    }
298	
299	    apply_schedule();
300	}
301	
302	/// Submit or cancel the `BGProcessingTask` request to match the current settings: a pending
303	/// request when background backups are enabled (carrying the external-power preference), or
304	/// none when they're off. Called at launch, whenever the settings change, and to re-arm the
305	/// next run as the task fires. The launch handler must already be registered.
306	#[cfg(target_os = "ios")]
307	fn apply_schedule() {
308	    use objc2_background_tasks::BGTaskScheduler;
309	    use objc2_foundation::NSString;
310	
311	    let scheduler = unsafe { BGTaskScheduler::sharedScheduler() };
312	    let identifier = NSString::from_str(BACKUP_TASK_IDENTIFIER);
313	    let settings = load_settings();
314	    if settings.background_enabled {
315	        schedule_next(&scheduler, &identifier, settings.require_external_power);
316	    } else {
317	        // Drop any pending request so a disabled setting takes effect immediately.
318	        unsafe { scheduler.cancelTaskRequestWithIdentifier(&identifier) };
319	    }
320	}
321	
322	/// Whether the device's default route is currently a cellular (WWAN) link, via
323	/// `SCNetworkReachability` flags for the unspecified address (general internet reachability).
324	/// On any read failure we report `false` (not cellular) so a diagnostic hiccup never silently
325	/// disables backups — an occasional cellular sweep is the lesser evil than a mirror that
326	/// quietly stops updating.
327	#[cfg(target_os = "ios")]
328	fn on_cellular() -> bool {
329	    use std::net::{Ipv4Addr, SocketAddr};
330	    use system_configuration::network_reachability::{ReachabilityFlags, SCNetworkReachability};
331	
332	    let addr = SocketAddr::from((Ipv4Addr::UNSPECIFIED, 0));
333	    let reachability = SCNetworkReachability::from(addr);
334	    match reachability.reachability() {
335	        Ok(flags) => {
336	            flags.contains(ReachabilityFlags::REACHABLE)
337	                && flags.contains(ReachabilityFlags::IS_WWAN)
338	        }
339	        Err(e) => {
340	            tracing::warn!(error = ?e, "background media backup: could not read network type; assuming not cellular");
341	            false
342	        }
343	    }
344	}
345	
346	/// The launch-handler body (runs on the main thread): re-arm the next run, then kick off the
347	/// sweep on the tokio runtime and wire up completion + expiration.
348	#[cfg(target_os = "ios")]
349	fn handle_launch(
350	    app: &tauri::AppHandle,
351	    task: objc2::rc::Retained<objc2_background_tasks::BGTask>,
352	) {
353	    use block2::RcBlock;
354	    use std::sync::atomic::AtomicBool;
355	    use std::sync::Arc;
356	
357	    // Re-arm the follow-up immediately (Apple's guidance is to submit the next request as the
358	    // task begins), so the mirror keeps getting topped up run after run. Via `apply_schedule`
359	    // so a disable toggled between fires cancels instead of re-submitting.
360	    apply_schedule();
361	
362	    // Share the task + a one-shot completion latch between the worker and the expiration
363	    // handler so the task is marked complete exactly once.
364	    let task = Arc::new(SendTask(task));
365	    let done = Arc::new(AtomicBool::new(false));
366	
367	    // Run the actual sweep off the main thread.
368	    let worker = {
369	        let app = app.clone();
370	        let task = task.clone();
371	        let done = done.clone();
372	        tauri::async_runtime::spawn(async move {
373	            let _ = run_backup_sweep(&app).await;
374	            complete_once(&task, &done, true);
375	        })
376	    };
377	
378	    // iOS calls this (on the main thread) when our time is nearly up: abort the sweep and end
379	    // cleanly. Aborting mid-pass is safe — the mirror write is atomic and the manifest is
380	    // checkpointed, so the interrupted DID simply resumes on the next sweep.
381	    let expiration = {
382	        let task = task.clone();
383	        RcBlock::new(move || {
384	            worker.abort();
385	            complete_once(&task, &done, false);
386	        })
387	    };
388	    unsafe { task.0.setExpirationHandler(Some(&expiration)) };
389	}
390	
391	/// Build and submit the next `BGProcessingTaskRequest`. Failures (the simulator has no
392	/// `BGTaskScheduler`; an unpermitted identifier; too many pending requests) are logged, never
393	/// fatal.
394	#[cfg(target_os = "ios")]
395	fn schedule_next(
396	    scheduler: &objc2_background_tasks::BGTaskScheduler,
397	    identifier: &objc2_foundation::NSString,
398	    require_external_power: bool,
399	) {
400	    use objc2::AnyThread;
401	    use objc2_background_tasks::BGProcessingTaskRequest;
402	    use objc2_foundation::NSDate;
403	
404	    let request = unsafe {
405	        BGProcessingTaskRequest::initWithIdentifier(BGProcessingTaskRequest::alloc(), identifier)
406	    };
407	    unsafe {
408	        // The sweep fetches blobs, so it always needs the network. External power follows the
409	        // user's "only while charging" setting (off by default so the sweep isn't starved on
410	        // devices that rarely charge on a predictable schedule). "Wi-Fi only" can't be
411	        // expressed here — it is enforced at fire time in `run_backup_sweep`.
412	        request.setRequiresNetworkConnectivity(true);
413	        request.setRequiresExternalPower(require_external_power);
414	        let earliest = NSDate::dateWithTimeIntervalSinceNow(EARLIEST_BEGIN_AFTER_SECS);
415	        request.setEarliestBeginDate(Some(&earliest));
416	    }
417	
418	    // A `BGProcessingTaskRequest` is a `BGTaskRequest`; `submitTaskRequest_error` takes the
419	    // superclass (deref coercion).
420	    if let Err(e) = unsafe { scheduler.submitTaskRequest_error(&request) } {
421	        tracing::warn!(error = ?e, "background media backup: failed to submit task request");
422	    }
423	}
