427	#[cfg(test)]
428	mod tests {
429	    use super::*;
430	    use blob_backup::BlobBackupError;
431	    use std::sync::atomic::{AtomicUsize, Ordering};
432	    use std::sync::Mutex;
433	
434	    fn dids(names: &[&str]) -> Vec<String> {
435	        names.iter().map(|s| s.to_string()).collect()
436	    }
437	
438	    #[tokio::test]
439	    async fn sweep_backs_up_only_opted_in_identities() {
440	        let all = dids(&["did:plc:a", "did:plc:b", "did:plc:c"]);
441	        // b is opted out.
442	        let enabled = |did: &str| did != "did:plc:b";
443	        let backed_up = Mutex::new(Vec::new());
444	
445	        let report = run_sweep_with(&all, enabled, |did| {
446	            let backed_up = &backed_up;
447	            async move {
448	                backed_up.lock().unwrap().push(did);
449	                Ok(())
450	            }
451	        })
452	        .await;
453	
454	        assert_eq!(
455	            report,
456	            BackupSweepReport {
457	                attempted: 2,
458	                succeeded: 2,
459	                failed: 0,
460	                skipped: 1,
461	            }
462	        );
463	        assert_eq!(
464	            *backed_up.lock().unwrap(),
465	            vec!["did:plc:a".to_string(), "did:plc:c".to_string()]
466	        );
467	    }
468	
469	    #[tokio::test]
470	    async fn sweep_degrades_per_did_and_continues() {
471	        let all = dids(&["did:plc:a", "did:plc:b", "did:plc:c"]);
472	        let attempts = AtomicUsize::new(0);
473	
474	        // The middle identity fails; the sweep must still attempt the third.
475	        let report = run_sweep_with(
476	            &all,
477	            |_| true,
478	            |did| {
479	                let attempts = &attempts;
480	                async move {
481	                    attempts.fetch_add(1, Ordering::SeqCst);
482	                    if did == "did:plc:b" {
483	                        Err(BlobBackupError::NetworkError {
484	                            message: "boom".to_string(),
485	                        })
486	                    } else {
487	                        Ok(())
488	                    }
489	                }
490	            },
491	        )
492	        .await;
493	
494	        assert_eq!(attempts.load(Ordering::SeqCst), 3);
495	        assert_eq!(
496	            report,
497	            BackupSweepReport {
498	                attempted: 3,
499	                succeeded: 2,
500	                failed: 1,
501	                skipped: 0,
502	            }
503	        );
504	    }
