506	    #[tokio::test]
507	    async fn sweep_with_no_opted_in_identities_does_nothing() {
508	        let all = dids(&["did:plc:a", "did:plc:b"]);
509	        let called = AtomicUsize::new(0);
510	
511	        let report = run_sweep_with(
512	            &all,
513	            |_| false,
514	            |did| {
515	                let called = &called;
516	                async move {
517	                    called.fetch_add(1, Ordering::SeqCst);
