543	    #[test]
544	    fn wifi_only_skips_only_on_cellular() {
545	        // Skip only when the user asked for Wi-Fi only AND we're on cellular.
546	        assert!(should_skip_for_network(true, true));
547	        assert!(!should_skip_for_network(true, false));
548	        // Wi-Fi-only off: never skip, cellular or not.
